'use strict';

/**
 * Research's walls as the running app applies them (issue #230,
 * docs/designs/research-agent-privacy.md). web-access.test.cjs pins the pure
 * decisions and the source lines; this drives the real HookServer and the
 * settings HiveManager writes, so a wiring change in hooks.ts or hive.ts that
 * leaves the pure rules intact still fails here.
 *
 * Generated by the /ship coverage audit (Step 7, 2026-10-13).
 */

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const loadTs = require('./load-ts.cjs');
const { posixOnly } = require('./platform.cjs');

const electron = require.resolve('electron');
require.cache[electron] = { id: electron, filename: electron, loaded: true, exports: { Notification: class { show() {} static isSupported() { return false; } } } };
const { HiveManager } = loadTs('src/main/hive.ts');
const { HookServer } = loadTs('src/main/hooks.ts');
const R = loadTs('src/shared/research.ts');
const W = loadTs('src/shared/webAccess.ts');
const F = loadTs('src/shared/folderAccess.ts');

const denied = (r) => !!(r && r.hookSpecificOutput && r.hookSpecificOutput.permissionDecision === 'deny');
const reason = (r) => r && r.hookSpecificOutput && r.hookSpecificOutput.permissionDecisionReason;

/** One office on disk: Michael in the business folder, Pam in a team folder
 *  inside it, and (unless `research` is false) Research at its desk. */
async function office(t, { research = true, on = research } = {}) {
  const base = fs.realpathSync.native(fs.mkdtempSync(path.join(os.tmpdir(), 'md-research-walls-')));
  t.after(() => fs.rmSync(base, { recursive: true, force: true }));
  const home = path.join(base, 'HarnessAgents');
  const business = path.join(base, 'Harbor Pizza');
  const pamDir = path.join(business, 'Admin');
  const desk = path.join(home, R.RESEARCH_DESK_DIR);
  for (const d of [home, business, pamDir, desk]) fs.mkdirSync(d, { recursive: true });
  const hive = new HiveManager(() => home);
  await hive.ensureAgent({ id: 'god', name: 'Michael', provider: 'claude', cwd: business, isGod: true });
  await hive.ensureAgent({ id: 'pam', name: 'Pam', provider: 'claude', cwd: pamDir });
  if (research) await hive.ensureAgent({ id: R.RESEARCH_ID, name: 'Research', provider: 'claude', cwd: desk, isResearch: true });
  // Who Research is comes from the app (the owner's switch), not the registry.
  hive.setResearchEnabled(() => on);
  const cfg = { harnessHome: home, businessFolder: business, businessTeam: [{ agentId: 'pam', folder: pamDir }] };
  return { base, home, business, pamDir, desk, hive, cfg };
}

function hookFor(o, extra = {}) {
  const server = new HookServer(
    o.hive, () => null, () => o.cfg,
    undefined, undefined, undefined, undefined,
    extra.getKnowledge, extra.getCompanyProfile
  );
  const cwdOf = (id) => (id === R.RESEARCH_ID ? o.desk : id === 'god' ? o.business : o.pamDir);
  return (agent_id, event, fields = {}) => server.handle({ agent_id, session_id: 's1', hook_event_name: event, cwd: cwdOf(agent_id), ...fields });
}

test('the running hook refuses web pages and search to everyone but Research, and fails closed', async (t) => {
  // Value: protects=only Research reaches a website, Michael included, and an unreadable registry refuses; fails_when=hooks.ts reads Research from config, skips Michael, ignores the app's mark, or lets an error through; why_new=web-access.test.cjs pins hooks.ts source text only; seam=none; no_claim=Claude Code obeying the deny (hook output shape from its schema)
  const o = await office(t);
  const hook = hookFor(o);
  const web = (id, tool) => hook(id, 'PreToolUse', { tool_name: tool, tool_input: { url: 'https://example.com', query: 'flour prices' } });
  for (const tool of ['WebFetch', 'WebSearch']) {
    assert.equal(reason(web('pam', tool)), R.REFUSAL_WEB_TOOL, `pam ${tool}`);
    assert.equal(reason(web('god', tool)), R.REFUSAL_WEB_TOOL, `Michael ${tool}`);
    assert.ok(!denied(web(R.RESEARCH_ID, tool)), `Research ${tool}`);
  }
  assert.ok(!denied(web('pam', 'Bash')), 'other tools are not this gate\'s');

  // A member that marks itself Research in the registry gets nothing (ship review D2.7).
  const reg = JSON.parse(fs.readFileSync(path.join(o.hive.root(), 'registry.json'), 'utf8'));
  reg.agents.pam.isResearch = true;
  fs.writeFileSync(path.join(o.hive.root(), 'registry.json'), JSON.stringify(reg));
  assert.equal(reason(web('pam', 'WebFetch')), R.REFUSAL_WEB_TOOL, 'a registry flag does not make Pam Research');

  // With the owner's switch off, the reserved id is refused too, and says so.
  const off = await office(t, { on: false });
  const offHook = hookFor(off);
  assert.equal(reason(offHook(R.RESEARCH_ID, 'PreToolUse', { tool_name: 'WebFetch', tool_input: { url: 'https://example.com' } })), R.REFUSAL_WEB_TOOL_OFF);
  assert.equal(reason(offHook('pam', 'PreToolUse', { tool_name: 'WebSearch', tool_input: { query: 'x' } })), R.REFUSAL_WEB_TOOL_OFF, 'Research off says so');

  // An office with no business folder keeps the internet (ship review D3).
  const dev = await office(t);
  dev.cfg = { harnessHome: dev.home };
  assert.ok(!denied(hookFor(dev)('pam', 'PreToolUse', { tool_name: 'WebFetch', tool_input: { url: 'https://example.com' } })));

  // Unreadable settings: refuse, never allow.
  o.cfg = null;
  const broken = new HookServer(o.hive, () => null, () => { throw new Error('config mid write'); });
  assert.equal(reason(broken.handle({ agent_id: R.RESEARCH_ID, session_id: 's1', hook_event_name: 'PreToolUse', cwd: o.desk, tool_name: 'WebFetch', tool_input: { url: 'https://example.com' } })), W.WEB_SETTINGS_UNREADABLE);
});

test('the running hook keeps Research out of the office\'s files and everyone else out of Research\'s folders', async (t) => {
  // Value: protects=Research's file tools open nothing of the office, its own folders stay open, and no member writes into its inbox; fails_when=folderCheck stops building the walled list, drops the own folders, or skips the wall for Michael; why_new=web-access.test.cjs tests the pure decisions, never the HookServer wiring; seam=none; no_claim=the sandbox enforcing the shell (settings only)
  const o = await office(t);
  const hook = hookFor(o);
  const call = (id, tool, file) => hook(id, 'PreToolUse', { tool_name: tool, tool_input: tool === 'Write' ? { file_path: file, content: 'x' } : { file_path: file } });
  const researchDir = path.join(o.hive.root(), 'agents', R.RESEARCH_ID);
  for (const file of [
    path.join(o.hive.root(), 'tasks.json'),
    path.join(o.hive.root(), 'agents', 'pam', 'inbox', 'm1.json'),
    path.join(o.business, 'Finance', 'ledger.xlsx'),
    path.join(o.pamDir, 'customers.csv')
  ]) {
    const r = call(R.RESEARCH_ID, 'Read', file);
    assert.ok(denied(r), `Research must not read ${path.relative(o.base, file)}`);
    assert.match(reason(r), /kept from you on purpose/);
  }
  assert.ok(!denied(call(R.RESEARCH_ID, 'Write', path.join(researchDir, 'outbox', 'a.json'))), 'its own outbox, inside the walled home');
  assert.ok(!denied(call(R.RESEARCH_ID, 'Read', path.join(o.desk, 'notes.md'))), 'its desk');
  // It writes nowhere else, inside the walls or out (ship review D2.6).
  for (const file of [path.join(os.homedir(), '.claude', 'settings.json'), path.join(o.base, 'outside', 'x.txt')]) {
    const r = call(R.RESEARCH_ID, 'Write', file);
    assert.ok(denied(r), `Research must not write ${file}`);
    assert.match(reason(r), /only in your own desk/);
  }
  // It reads nothing in the home folder outside its own (D2.5).
  assert.ok(denied(call(R.RESEARCH_ID, 'Read', path.join(os.homedir(), '.claude', 'projects', 'x.jsonl'))));

  for (const id of ['pam', 'god']) {
    assert.ok(denied(call(id, 'Write', path.join(researchDir, 'inbox', 'sneak.json'))), `${id} must not write Research's inbox`);
    assert.ok(denied(call(id, 'Write', path.join(o.desk, 'x.md'))), `${id} must not write Research's desk`);
    // Its folders are its alone: nobody else reads its raw web text (owner, 2026-10-13).
    for (const file of [path.join(o.desk, 'notes.md'), path.join(researchDir, 'outbox', 'a.json'), path.join(researchDir, 'memory', 'inbox.md')]) {
      const r = call(id, 'Read', file);
      assert.ok(denied(r), `${id} must not read ${path.relative(o.base, file)}`);
      assert.match(reason(r), /only Research reads it/);
    }
    assert.ok(!denied(call(id, 'Read', path.join(o.hive.root(), 'tasks.json'))), `${id} still reads the hive`);
  }

  // An office with no business folder has no hive write guard: the Research
  // wall alone keeps a member from dropping a message into its inbox.
  const business = o.cfg;
  o.cfg = { harnessHome: o.home };
  for (const id of ['pam', 'god']) {
    for (const file of [path.join(researchDir, 'inbox', 'sneak.json'), path.join(o.desk, 'x.md')]) {
      const r = call(id, 'Write', file);
      assert.ok(denied(r), `${id} must not write ${path.relative(o.base, file)} (no business folder)`);
      assert.match(reason(r), /That is Research's folder/);
    }
  }
  assert.ok(!denied(call(R.RESEARCH_ID, 'Write', path.join(o.desk, 'notes.md'))), 'Research writes its desk (no business folder)');

  // Its desk is its own folder (folderAccess.ts: "its agent folder and its
  // desk"), so its file tools write there on a business office too.
  o.cfg = business;
  const own = call(R.RESEARCH_ID, 'Write', path.join(o.desk, 'notes.md'));
  assert.ok(!denied(own), `Research writes its own desk on a business office; refused with: ${reason(own)}`);
});

test('the settings written at spawn take the internet from a member\'s shell and fence Research\'s writes', posixOnly('Claude Code has no shell sandbox on Windows, so no network list is written'), async (t) => {
  // Value: protects=a member's shell reaches no host even with no business folder, and Research's shell writes only its own folders; fails_when=hookSettings drops network or sandbox only, or sandboxWritableDirs gives Research the hive; why_new=no test reads the settings file for network or Research's allowWrite; seam=none; no_claim=Claude Code honouring an empty strict list (verified live by the author, not here)
  const o = await office(t, { research: false });
  const settingsOf = (inj) => JSON.parse(fs.readFileSync(inj.args[inj.args.indexOf('--settings') + 1], 'utf8'));

  // A member of an office with no business folder: no folder policy at all.
  const member = settingsOf(await o.hive.ensureAgent(
    { id: 'kelly', name: 'Kelly', provider: 'claude', cwd: o.pamDir },
    { network: W.sandboxNetwork(false) }
  ));
  assert.deepEqual(member.sandbox.network, { allowedDomains: [], strictAllowlist: true });
  assert.equal(member.sandbox.allowUnsandboxedCommands, false, 'a rerun outside the sandbox would reach the internet');

  // Research: no network list, and writes only its agent folder and its desk.
  const researchDir = path.join(o.hive.root(), 'agents', R.RESEARCH_ID);
  const research = settingsOf(await o.hive.ensureAgent(
    { id: R.RESEARCH_ID, name: 'Research', provider: 'claude', cwd: o.desk, isResearch: true },
    { folderPolicy: F.researchFolderPolicy([o.base, o.home, o.business], [researchDir, o.desk], o.base), extraWritableDirs: [] }
  ));
  assert.equal(research.sandbox.network, undefined);
  assert.deepEqual([...research.sandbox.filesystem.allowWrite].sort(), [researchDir, o.desk].sort());
  assert.ok(!research.sandbox.filesystem.allowWrite.includes(o.hive.root()), 'never the hive');
  assert.deepEqual([...research.permissions.additionalDirectories].sort(), [researchDir, o.desk].sort());
  // The home folder is walled for reads, and its riskiest places for edits (D2.5, D2.6).
  assert.ok(research.sandbox.filesystem.denyRead.includes(o.base));
  assert.ok(research.permissions.deny.includes(`Edit(/${path.join(o.base, '.claude')}/**)`), 'an absolute rule, not settings relative');
  assert.ok(research.permissions.deny.includes(`Edit(/${path.join(o.base, '.zshrc')})`));
  // Every other agent is walled from Research's folders for reads too.
  const pam = F.withResearchWall(F.folderPolicy({ isGod: false, cwd: o.pamDir }, { business: o.business, teamFolders: [o.pamDir] }, true), [researchDir, o.desk]);
  for (const d of [researchDir, o.desk]) {
    assert.ok(pam.sandbox.denyRead.includes(d) && pam.sandbox.denyWrite.includes(d), d);
    assert.ok(pam.deny.includes(`Read(/${d}/**)`) && pam.deny.includes(`Edit(/${d}/**)`), d);
  }
});

test('a message the app delivered to Research survives an app restart; the stamp key stays out of the hive', async (t) => {
  // Value: protects=asks waiting for Research when the app restarts are not swept as forged, and agents cannot read the key to forge a stamp; fails_when=the stamp key is not saved, is saved in the hive, or changes per run; why_new=research-routing.test.cjs checks the sweep within one HiveManager only; seam=none; no_claim=file mode 0600 on Windows (fake privacy guard stands in for the model check)
  const o = await office(t);
  o.hive.setTrustLayer({ inbound: async (m) => ({ decision: 'pass', subject: m.subject, body: m.body }), outbound: async () => ({ decision: 'deny', reason: 'x' }) });
  fs.writeFileSync(path.join(o.hive.root(), 'agents', 'pam', 'outbox', 'm1.json'), JSON.stringify({ to: 'research', act: 'query', subject: 'Flour', body: 'Flour suppliers in Austin' }));
  o.hive.routeOnce();
  await new Promise((r) => setImmediate(r));
  assert.equal(o.hive.routeOnce(), 1);
  const inbox = path.join(o.hive.root(), 'agents', R.RESEARCH_ID, 'inbox');
  const waiting = () => fs.readdirSync(inbox).filter((f) => f.endsWith('.json'));
  assert.equal(waiting().length, 1);

  // The app restarts: a new HiveManager over the same home.
  const again = new HiveManager(() => o.home);
  again.setResearchEnabled(() => true);
  again.routeOnce();
  assert.equal(waiting().length, 1, 'the delivered ask is still waiting');

  const keyFile = path.join(o.home, 'private', 'research-stamp.key');
  assert.ok(fs.existsSync(keyFile), 'the key is kept in the app\'s private folder');
  assert.ok(path.relative(o.hive.root(), keyFile).startsWith('..'), 'the key is not inside the hive any agent reads');
});

test('Research is never handed the company profile or company knowledge; a teammate is', async (t) => {
  // Value: protects=the business's facts never reach the one agent on the internet; fails_when=the isResearchAgent check in hooks.ts is dropped or reads the wrong agent; why_new=research-routing.test.cjs covers the spawn prompt only, not the per session hook context; seam=none; no_claim=what Claude Code does with the context it is given
  const o = await office(t);
  const PROFILE = 'COMPANY PROFILE. Harbor Pizza, owner Dana Lee, revenue 1.2M';
  const hook = hookFor(o, {
    getCompanyProfile: () => PROFILE,
    getKnowledge: () => ({ active: true, cliPath: '/kg', root: path.join(o.home, 'kg') })
  });
  const text = (r) => JSON.stringify(r ?? {});
  assert.match(text(hook('pam', 'SessionStart', { source: 'startup' })), /owner Dana Lee/, 'a teammate gets the profile');
  for (const event of ['SessionStart', 'UserPromptSubmit']) {
    const r = text(hook(R.RESEARCH_ID, event, { source: 'startup', prompt: 'go' }));
    assert.doesNotMatch(r, /Dana Lee|COMPANY PROFILE/, `Research ${event}`);
    assert.doesNotMatch(r, /COMPANY KNOWLEDGE/i, `Research ${event}: knowledge`);
  }
});

test('Research can\'t search from a folder above a wall, nor follow a link out of its desk', async (t) => {
  // Value: protects=a Grep on "/" or a parent folder, or a link in the desk, can't read the office's files; fails_when=the wall checks only targets inside it, or the real path check is dropped; why_new=red team and testing review pass 2; seam=none; no_claim=ripgrep's own traversal
  const o = await office(t);
  const hook = hookFor(o);
  const call = (tool, input) => hook(R.RESEARCH_ID, 'PreToolUse', { tool_name: tool, tool_input: input });
  assert.ok(denied(call('Grep', { pattern: 'owes', path: '/' })), 'Grep on /');
  assert.ok(denied(call('Grep', { pattern: 'owes', path: o.base })), 'Grep on a folder holding the business folder');
  assert.ok(denied(call('Glob', { pattern: `${o.base}/**` })), 'Glob from above');
  assert.ok(!denied(call('Grep', { pattern: 'flour', path: o.desk })), 'its own desk is fine');
  if (process.platform !== 'win32') {
    fs.writeFileSync(path.join(o.business, 'ledger.csv'), 'x');
    fs.symlinkSync(path.join(o.business, 'ledger.csv'), path.join(o.desk, 'link.csv'));
    for (const tool of ['Read', 'Write']) {
      assert.ok(denied(call(tool, { file_path: path.join(o.desk, 'link.csv'), content: 'y' })), `${tool} through a link`);
    }
  }
});

test('Research\'s file tools open no temporary folder, and no office agent keeps its session files in /tmp', posixOnly('temporary folder paths'), async (t) => {
  // Value: protects=teammates' command output and scratch files never reach the agent that talks to the internet; fails_when=temp folders leave Research's walls, or an agent's session files go back to the shared /tmp; why_new=ship review D6.1 (owner chose A after a live check 2026-10-13); seam=none; no_claim=Claude Code honoring CLAUDE_CODE_TMPDIR (checked live)
  const o = await office(t);
  const hook = hookFor(o);
  const read = (file) => hook(R.RESEARCH_ID, 'PreToolUse', { tool_name: 'Read', tool_input: { file_path: file } });
  assert.ok(denied(read(`/private/tmp/claude-${process.getuid()}/-Users-pam-Sales/s1/tasks/x.output`)), 'another session\'s output');
  assert.ok(denied(read(path.join(os.tmpdir(), 'other-app.txt'))), 'the per user temp folder');
  assert.ok(!denied(read(path.join(o.desk, F.RESEARCH_TMP_DIR, 'scratch.txt'))), 'its own session files, in its desk');
  // The shell keeps /tmp (Claude Code's own working files) and is walled from the rest.
  const shell = F.shellTempWalls('darwin', '/var/folders/ab/T');
  assert.ok(!shell.includes('/tmp') && !shell.includes('/private/tmp'));
  assert.ok(shell.includes('/private/var/folders') && shell.includes('/var/folders/ab/T'));
  const main = fs.readFileSync(path.join(__dirname, '..', 'src/main/index.ts'), 'utf8');
  assert.match(main, /const dir = isResearch \? join\(opts\.cwd, RESEARCH_TMP_DIR\) : harness \? join\(expandTilde\(harness\), AGENT_TMP_DIR, opts\.hive\.id\) : '';/);
  assert.match(main, /if \(sessionTmp\) opts\.env = \{ \.\.\.opts\.env, CLAUDE_CODE_TMPDIR: sessionTmp \};/);
  assert.match(main, /extraWritableDirs: \[memory\.env\(\)\.MEMPALACE_PALACE_PATH, sessionTmp\]/);
});
